export const KEY_SIGNATURE_SHARP_ORDER = ["F", "C", "G", "D", "A", "E", "B"] as const;
export const KEY_SIGNATURE_FLAT_ORDER = ["B", "E", "A", "D", "G", "C", "F"] as const;
export const SPELLING_ACCIDENTAL_CANDIDATES = [-2, -1, 0, 1, 2] as const;

export const MIDI_STATEFUL_PROFILE_ID = "MIDI_STATEFUL_MBC2015_V1" as const;
export const MIDI_CHORD_PROFILE_ID = "MIDI_GENERIC_UPPER_NOTE_DOWNWARD_INTERVALS_V1" as const;
export const KEYBOARD_DIRECTIONAL_CHORD_PROFILE_ID = "MBC2015_KEYBOARD_RH_DOWN_LH_UP_V1" as const;

export interface SpelledPitch {
  readonly midiPitch: number;
  readonly step: MusicNoteName;
  readonly accidental: -2 | -1 | 0 | 1 | 2;
  readonly scientificOctave: number;
  readonly display: string;
}

